# Function: download_ghcn_data

import csv
import io
import os
import tempfile

import requests

GHCN_URL = (
    "https://www.ncei.noaa.gov/data/global-historical-climatology-network-daily/"
    "access/USC00351862.csv"
)
REQUIRED_COLUMNS = ("DATE", "PRCP", "TMIN", "TMAX")


def download_ghcn_data(folder: str, output1: str) -> None:
    faasr_log(f"Downloading GHCN-Daily CSV from {GHCN_URL}")
    try:
        resp = requests.get(GHCN_URL, timeout=(15, 300))
        resp.raise_for_status()
    except requests.RequestException as e:
        faasr_log(f"ERROR: failed to download {GHCN_URL}: {e}")
        raise

    content = resp.content
    if not content or not content.strip():
        msg = f"ERROR: empty response from {GHCN_URL}"
        faasr_log(msg)
        raise RuntimeError(msg)

    text = content.decode("utf-8-sig", errors="replace")
    reader = csv.reader(io.StringIO(text))
    try:
        header = [h.strip() for h in next(reader)]
    except StopIteration:
        msg = "ERROR: downloaded CSV has no header row"
        faasr_log(msg)
        raise RuntimeError(msg)

    missing = [c for c in REQUIRED_COLUMNS if c not in header]
    if missing:
        msg = f"ERROR: downloaded CSV is missing required columns {missing}; header={header[:20]}"
        faasr_log(msg)
        raise RuntimeError(msg)

    date_idx = header.index("DATE")
    n_rows = 0
    min_date = None
    max_date = None
    for row in reader:
        if not row:
            continue
        n_rows += 1
        if date_idx < len(row):
            d = row[date_idx].strip()
            if d:
                if min_date is None or d < min_date:
                    min_date = d
                if max_date is None or d > max_date:
                    max_date = d

    if n_rows == 0:
        msg = "ERROR: downloaded CSV contains a header but no data rows"
        faasr_log(msg)
        raise RuntimeError(msg)

    faasr_log(f"Downloaded {n_rows} rows; date range {min_date} to {max_date}")

    tmpdir = tempfile.mkdtemp()
    local_path = os.path.join(tmpdir, output1)
    with open(local_path, "wb") as f:
        f.write(content)

    faasr_put_file(local_file=local_path, remote_folder=folder, remote_file=output1)
    faasr_log(f"Uploaded raw CSV to {folder}/{output1}")
